base.src/analytics/track.ts:
export function track(event: string, properties: Record<string, unknown>): void {
  void fetch("/events", { method: "POST", body: JSON.stringify({ event, properties }) });
}

base.src/analytics/bus.ts:
type Listener = (payload: Record<string, unknown>) => void;

const listeners = new Map<string, Listener[]>();

export function on(topic: string, listener: Listener): void {
  listeners.set(topic, [...(listeners.get(topic) ?? []), listener]);
}

export function publish(topic: string, payload: Record<string, unknown>): void {
  for (const listener of listeners.get(topic) ?? []) listener(payload);
}

