import { publish } from "../analytics/bus";

export interface CartItem {
  id: string;
  priceCents: number;
}

const items: CartItem[] = [];

export function add(item: CartItem): void {
  items.push(item);
  publish("cart:add", { id: item.id, priceCents: item.priceCents });
}

